package glitch

import data.glitch_lib

# Unencrypted protocols and their indicators
unencrypted_protocols := {"http", "ftp", "telnet", "smtp", "ldap"}

unencrypted_variants := {"disable_tls", "disable_ssl", "no_encryption", "allow_plaintext", "allow_insecure", "insecure", "plain", "unencrypted", "cleartext", "http_only", "allow_http", "enable_http", "insecure_registries", "registry_insecure"}

tls_disabled_keywords := {"tls_disabled", "ssl_disabled", "tls_enabled", "ssl_enabled", "use_tls", "enable_tls", "require_tls", "enforce_tls", "tls_required", "ssl_required", "force_ssl", "require_ssl", "rds_force_ssl", "redirect_https", "ssl_redirect"}

# Deprecated TLS versions
deprecated_tls_versions := {"1.0", "1.1", "SSLv3", "TLSv1", "TLSv1_0", "TLSv1_1"}

# Certificate validation bypass keywords
skip_verify_keywords := {"skip_tls_verify", "insecure_skip_verify", "validate_certs", "reject_unauthorized", "allow_self_signed", "self_signed_cert", "insecure_skip_tls_verify"}

# Secure transfer keywords that should be true/enabled
secure_transfer_keywords := {"secure_transfer_required", "https_traffic_only", "secure_transfer_enabled", "https_only", "require_secure_transport", "min_tls_version", "minimum_tls_version", "tls_version"}

# Encryption in transit keywords
encryption_transit_keywords := {"inflight_encryption", "encryption_in_transit", "encrypt", "ssl_mode", "ssl", "encrypt_in_transit"}

# Helper to check if value contains unencrypted protocol
is_unencrypted_protocol(value) {
    value.ir_type == "String"
    lower_value := lower(value.value)
    protocol := unencrypted_protocols[_]
    lower_value == protocol
}

is_unencrypted_protocol(value) {
    value.ir_type == "String"
    lower_value := lower(value.value)
    protocol := unencrypted_protocols[_]
    startswith(lower_value, protocol)
    not contains(lower_value, "s")  # not https, ftps, etc.
}

# Helper to check for TLS disablement patterns
is_tls_disabled(attr) {
    attr.name == tls_disabled_keywords[_]
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

is_tls_disabled(attr) {
    attr_name_lower := lower(attr.name)
    contains(attr_name_lower, "disable")
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

is_tls_disabled(attr) {
    attr.name == "ssl_mode"
    attr.value.ir_type == "String"
    lower(attr.value.value) in {"disable", "disabled", "false", "no", "off", "optional", "prefer"}
}

is_tls_disabled(attr) {
    attr.name == "encrypt"
    attr.value.ir_type == "String"
    lower(attr.value.value) in {"disable", "disabled", "false", "no", "off", "optional", "prefer"}
}

is_tls_disabled(attr) {
    attr.name == "encrypt"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

# Helper to check for deprecated TLS version
is_deprecated_tls(attr) {
    attr.name == "tls_version"
    attr.value.ir_type == "String"
    lower(attr.value.value) == deprecated_tls_versions[_]
}

is_deprecated_tls(attr) {
    attr.name == "ssl_protocol_version"
    attr.value.ir_type == "String"
    lower(attr.value.value) == deprecated_tls_versions[_]
}

is_deprecated_tls(attr) {
    attr.name == "min_tls_version"
    attr.value.ir_type == "String"
    lower(attr.value.value) == deprecated_tls_versions[_]
}

is_deprecated_tls(attr) {
    attr.name == "minimum_tls_version"
    attr.value.ir_type == "String"
    lower(attr.value.value) == deprecated_tls_versions[_]
}

# Helper to check for certificate validation bypass
is_skip_verify(attr) {
    attr.name == skip_verify_keywords[_]
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

is_skip_verify(attr) {
    attr_name_lower := lower(attr.name)
    contains(attr_name_lower, "skip")
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

is_skip_verify(attr) {
    attr_name_lower := lower(attr.name)
    contains(attr_name_lower, "insecure")
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

is_skip_verify(attr) {
    attr.name == "allow_self_signed"
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

is_skip_verify(attr) {
    attr.name == "self_signed_cert"
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

# Helper to check for missing required encryption in sensitive contexts
has_sensitive_context(attrs) {
    attr := attrs[_]
    attr_name_lower := lower(attr.name)
    contains(attr_name_lower, "password")
}

has_sensitive_context(attrs) {
    attr := attrs[_]
    attr_name_lower := lower(attr.name)
    contains(attr_name_lower, "secret")
}

has_sensitive_context(attrs) {
    attr := attrs[_]
    attr_name_lower := lower(attr.name)
    contains(attr_name_lower, "credential")
}

has_sensitive_context(attrs) {
    attr := attrs[_]
    attr_name_lower := lower(attr.name)
    contains(attr_name_lower, "private_key")
}

has_sensitive_context(attrs) {
    attr := attrs[_]
    attr_name_lower := lower(attr.name)
    contains(attr_name_lower, "api_key")
}

has_sensitive_context(attrs) {
    attr := attrs[_]
    attr_name_lower := lower(attr.name)
    contains(attr_name_lower, "token")
}

has_sensitive_context(attrs) {
    attr := attrs[_]
    attr_name_lower := lower(attr.name)
    contains(attr_name_lower, "access_key")
}

# Check if encryption is missing when sensitive data is present
missing_encryption_with_sensitive(attrs) {
    has_sensitive_context(attrs)
    not has_encryption_enabled(attrs)
}

has_encryption_enabled(attrs) {
    attr := attrs[_]
    attr.name == secure_transfer_keywords[_]
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

has_encryption_enabled(attrs) {
    attr := attrs[_]
    attr.name == encryption_transit_keywords[_]
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

has_encryption_enabled(attrs) {
    attr := attrs[_]
    attr.name == encryption_transit_keywords[_]
    attr.value.ir_type == "String"
    lower(attr.value.value) == "required"
}

# Helper to check attribute name patterns
attr_name_contains_unencrypted(attr_name) {
    name_lower := lower(attr_name)
    keyword := unencrypted_variants[_]
    contains(name_lower, keyword)
}

# Protocol attribute with unencrypted value
is_protocol_insecure(attr) {
    attr_name_lower := lower(attr.name)
    (contains(attr_name_lower, "protocol") == true; contains(attr_name_lower, "scheme") == true)
    is_unencrypted_protocol(attr.value)
}

# URL attribute with unencrypted protocol
is_url_insecure(attr) {
    attr_name_lower := lower(attr.name)
    (contains(attr_name_lower, "url") == true; contains(attr_name_lower, "endpoint") == true; contains(attr_name_lower, "uri") == true)
    attr.value.ir_type == "String"
    startswith(lower(attr.value.value), "http://")
}

# Main rule: Unencrypted protocol usage
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_protocol_insecure(attr)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Unencrypted protocol detected where encrypted communication should be used. (CWE-319)"
    }
}

# Main rule: Insecure URL/endpoint
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_url_insecure(attr)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Insecure URL using HTTP instead of HTTPS. (CWE-319)"
    }
}

# Main rule: TLS/SSL explicitly disabled
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_tls_disabled(attr)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - TLS/SSL encryption is explicitly disabled. (CWE-319)"
    }
}

# Main rule: Deprecated TLS version
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_deprecated_tls(attr)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Deprecated TLS/SSL version in use, which provides weak encryption. (CWE-319)"
    }
}

# Main rule: Certificate validation bypassed
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_skip_verify(attr)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Certificate validation is disabled, susceptible to man-in-the-middle attacks. (CWE-319)"
    }
}

# Main rule: Unencrypted variants in attribute names with dangerous values
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr_name_contains_unencrypted(attr.name)
    attr.value.ir_type == "Boolean"
    attr.value.value == true

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Insecure communication pattern enabled. (CWE-319)"
    }
}

# Main rule: Insecure registry configuration
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    name_lower := lower(attr.name)
    contains(name_lower, "insecure_registries")
    attr.value.ir_type == "Array"
    count(attr.value.value) > 0

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Insecure container registries configured without TLS. (CWE-319)"
    }
}

# Main rule: Missing encryption with sensitive context
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    missing_encryption_with_sensitive(attrs)

    result := {
        "type": "sec_https",
        "element": node,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Sensitive data may be transmitted without encryption. (CWE-319)"
    }
}

